import type { ModelResult } from "./evidence";
import type { RequirementKind } from "./schemas";

/**
 * Demo fixtures. These are hand-authored rather than generated by a live AI run, so the
 * app opens with a full grid instantly, for free, and identically every time.
 *
 * They are NOT hand-written database rows. The seed script feeds these through the same
 * validateEvaluations() the live path uses, so every quote below is genuinely checked
 * against the CV text beside it. A typo in a quote fails the seed loudly instead of
 * quietly becoming a gap.
 */

export type SeedResult = ModelResult & {
  /**
   * Marks a claim whose quote is deliberately absent from the CV. Sofia below has one:
   * it exists so the seeded data itself demonstrates the guardrail catching an
   * unsupported must-have and disqualifying an otherwise strong candidate.
   */
  unsupported?: boolean;
};

